{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Codeine, the closest analogue, has an oral bioavailability of 0.50 in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Codeine sulfate in healthy subjects has an oral bioavailability of 80.5%, showing that the 3-methoxy-N-methyl morphinan scaffold can achieve high oral systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ethylmorphine, a close 3-alkoxy morphinan analogue, has a median systemic availability of 0.74 (range 0.54-0.92) in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Morphine, a related N-methyl morphinan, has an oral bioavailability of 30-40% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Noscapine, a structurally related morphinan, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Naltrexone, a less similar N-cyclopropylmethyl morphinan with phenolic 3-OH and 14-OH, has very poor oral bioavailability of about 5-10%, providing a low-F counterexample with limited transferability to the N-methyl, 3-methoxy query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 6-keto N-methyl morphinan (hydrocodone-like). The closest analogues, codeine and codeine sulfate, show high oral bioavailability (50-90%), and other N-methyl/3-alkoxy morphinans are mostly above 20%. The low-F naltrexone evidence is structurally distant and does not override the strong supportive pattern.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for the query molecule itself is present in the evidence set.",
    "The closest analogue, codeine, differs at the C6 position (hydroxy/enone vs ketone/saturated), so the exact effect of this change on first-pass metabolism is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

